from scipy.integrate import solve_ivp

def simulate(network, t_eval):
    species = network['species']
    species_index = {s['name']: i for i, s in enumerate(species)}
    n_species = len(species)
    y0 = np.array([s['initial'] for s in species])

    def deriv(t, y):
        dydt = np.zeros(n_species)
        for reaction in network['reactions']:
            product = 1.0
            for species_name, stoich in reaction['reactants'].items():
                product *= y[species_index[species_name]] ** stoich
            rate = reaction['rate'] * product
            for species_name in species:
                reactant_stoich = reaction['reactants'].get(species_name, 0)
                product_stoich = reaction['products'].get(species_name, 0)
                net_coeff = product_stoich - reactant_stoich
                dydt[species_index[species_name]] += net_coeff * rate
        return dydt

    sol = solve_ivp(deriv, [0, network['t_end']], y0, t_eval=t_eval, method='BDF', rtol=1e-4, atol=1e-5)
    return sol.y.T
"}

